pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Precondition: caller has non-zero balance before calling airDrop()
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        // Give caller some initial tokens to make the precondition hold
        vm.prank(address(0xdead)); // any address that can call airDrop with zero balance first
        // But we need to set caller's balance > 0. Use a helper: call airDrop from some other address that has zero balance
        address helper = address(0x1234);
        vm.assume(helper != caller && helper != address(0) && helper != address(c));
        vm.prank(helper);
        c.airDrop(); // helper now has 20 tokens
        // Now transfer 20 tokens from helper to caller via direct state manipulation? No, only public surface.
        // Instead, just use a different approach: directly set tokenBalance via a public function if available.
        // There is none. So we rely on fuzzing: we require that caller already has non-zero balance from a previous call.
        // But to guarantee that, we can call airDrop() from caller first with zero balance, which will succeed for reference.
        // After that, caller's balance becomes 20 > 0. Then a second call should revert in reference (due to hasNoBalance modifier).
        // In mutant, hasNoBalance requires !=0, so second call succeeds.
        // First call: assume caller has zero balance initially
        vm.assume(c.tokenBalance(caller) == 0);
        vm.prank(caller);
        c.airDrop(); // first call, should succeed
        // Now caller has 20 tokens (non-zero). Second call should revert in reference, succeed in mutant.
        bool reverted = false;
        vm.prank(caller);
        try c.airDrop() {} catch { reverted = true; }
        assertTrue(reverted, "airDrop should revert for non-zero balance caller");
    }
}

