    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Ensure the caller has zero balance initially
        vm.assume(c.tokenBalance(caller) == 0);
        // The caller must be the Bank contract for supportsToken to pass
        // We simulate this by making the caller a Bank that returns the correct support
        // But in the test we cannot change the caller's address; we can only prank a given caller
        // However, the supportsToken modifier checks Bank(msg.sender).supportsToken()
        // So to make the call succeed, we need to deploy a Bank contract and make msg.sender = that Bank
        // But then the caller address in the test would be the Bank address, not an arbitrary user.
        // Since the bug breaks the rule that the caller's balance increases, we can instead:
        // Deploy a Bank and use vm.prank to call airDrop from the Bank address.
        Bank bank = new Bank();
        vm.prank(address(bank));
        c.airDrop();
        assertTrue(c.tokenBalance(address(bank)) == 20);
    }
