contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(c.tokenBalance(caller) == 0);

        uint256 balanceBefore = c.tokenBalance(caller);

        // Prank as caller and call Bank to satisfy supportsToken
        vm.startPrank(caller);
        // We need to call airDrop from an address that returns the correct supportsToken
        // The caller must be a Bank contract that returns the correct hash
        // For simplicity, we'll use a known address (the contract itself or deploy a mock)
        // But the test must work generically; we'll use vm.assume to ensure the caller is the bank
