        // Since we can only use c's public surface, we must use the contract's own Bank
        // The simplest approach: use the contract's address as caller, but it doesn't have supportsToken
        // Instead, we'll just call airDrop from a prank that is a Bank contract
        // We'll deploy a Bank in setUp if needed
        c.airDrop();
        vm.stopPrank();

        uint256 balanceAfter = c.tokenBalance(caller);
        assertTrue(balanceAfter == balanceBefore + 20);
    }
