pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender) public {
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));

        // Ensure sender's balance is zero
        uint balanceBefore = c.tokenBalance(sender);
        vm.assume(balanceBefore == 0);

        // Deploy Bank and prank as sender to call supportsToken
        Bank bank = new Bank();
        vm.prank(address(bank));

        // Call airDrop as sender, expect revert if bank not set up properly
        // We need to set up so supportsToken passes. 
        // Since supportsToken checks msg.sender (the caller) returns keccak256("Nu Token"),
        // we can prank the bank address to call airDrop, but that would make bank the msg.sender.
        // Actually the correct setup: the call to airDrop must come from an address that Bank(msg.sender).supportsToken() returns the hash.
        // The simplest way: deploy Bank, then use vm.prank(bank) to call airDrop from bank's address.

        uint balanceBeforeCall = c.tokenBalance(address(bank));
        vm.assume(balanceBeforeCall == 0);

        vm.prank(address(bank));
        c.airDrop();

        uint balanceAfter = c.tokenBalance(address(bank));
        assertTrue(balanceAfter == balanceBeforeCall + 20);
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
